import QtQuick
import Quickshell
import Quickshell.Wayland
import qs.Commons
import qs.Ui

// Drawer button for the bar. Clicking it opens a card next to the bar that
// hosts the widgets listed in this entry's `items` setting in shell.json:
//
//   { "id": "parker.drawer", "items": ["omarchy.weather", { "id": "omarchy.clock", "format": "HH:mm" }] }
//
// Hosted widgets stay mounted while the drawer is closed, so their state,
// timers, and IPC targets keep working exactly as they did on the bar.
BarWidget {
  id: root

  // Bar-shaped popup contract: lets `omarchy-shell shell toggle parker.drawer`
  // and the numbered panel hotkeys open the drawer, and lets the bar's
  // one-popup-at-a-time coordinator close it when another panel opens.
  readonly property bool opened: drawerOpen
  property bool drawerOpen: false

  property QtObject service: null
  readonly property var registry: service ? service.barWidgetRegistry : null

  readonly property var barWindow: root.QsWindow.window
  readonly property string screenName: barWindow && barWindow.screen ? String(barWindow.screen.name || "") : ""
  readonly property string position: bar ? String(bar.position || "top") : "top"
  readonly property real barThickness: barWindow
    ? (vertical ? barWindow.width : barWindow.height)
    : barSize
  readonly property int gap: Style.gapsOut
  readonly property int margin: Style.gapsOut

  readonly property var configuredItems: Array.isArray(settings.items) ? settings.items : []

  // Only the identity of the hosted list drives the Repeater: settings edits
  // (a clock format cycling, say) patch the live widgets instead of rebuilding
  // them, because an unchanged string property does not notify.
  readonly property string hostedKey: JSON.stringify(computeHostedEntries())
  readonly property var hostedEntries: JSON.parse(hostedKey)

  property var hostedSlots: []
  property var openAfterShow: null

  property var tooltipTarget: null
  property string tooltipText: ""
  property bool tooltipShown: false
  property bool focusPrimed: false

  implicitWidth: button.implicitWidth
  implicitHeight: button.implicitHeight

  // ------------------------------------------------------------- lifecycle

  function open() {
    if (drawerOpen) return
    drawerOpen = true
    if (bar) bar.requestPopout(root)
  }

  function close() {
    if (!drawerOpen) return
    drawerBar.closeActivePopout()
    clearTooltip()
    openAfterShow = null
    drawerOpen = false
    if (bar) bar.releasePopout(root)
  }

  function closeForPopoutSwitch() { close() }

  function toggle() { drawerOpen ? close() : open() }

  onDrawerOpenChanged: {
    focusPrimeTimer.stop()
    focusPrimed = false
    if (drawerOpen) {
      focusPrimeTimer.start()
      Qt.callLater(function() { if (root.drawerOpen) keyCatcher.forceActiveFocus() })
    }
  }

  // ------------------------------------------------------- service lookup

  function lookupService() {
    if (service || !bar || !bar.shell || typeof bar.shell.serviceFor !== "function") return
    var found = bar.shell.serviceFor(root.moduleName)
    if (!found) return
    service = found
    if (typeof found.registerHost === "function") found.registerHost(root)
  }

  onBarChanged: lookupService()
  onModuleNameChanged: lookupService()
  Component.onCompleted: lookupService()
  Component.onDestruction: {
    if (service && typeof service.unregisterHost === "function") service.unregisterHost(root)
    if (bar) bar.releasePopout(root)
  }

  // The service is created alongside this widget and may land a moment later.
  Timer {
    interval: 250
    repeat: true
    running: !root.service && root.moduleName !== ""
    onTriggered: root.lookupService()
  }

  // --------------------------------------------------------- hosted items

  function entryId(entry) {
    if (typeof entry === "string") return entry
    if (Util.isPlainObject(entry) && entry.id !== undefined && entry.id !== null) return String(entry.id)
    return ""
  }

  function entrySettings(entry) {
    var copy = {}
    if (!Util.isPlainObject(entry)) return copy
    for (var key in entry) if (key !== "id") copy[key] = entry[key]
    return copy
  }

  function inBarLayout(id) {
    var layout = bar && bar.layoutConfig ? bar.layoutConfig : null
    if (!Util.isPlainObject(layout)) return false
    var sections = ["left", "center", "right"]
    for (var s = 0; s < sections.length; s++) {
      var entries = layout[sections[s]]
      if (!Array.isArray(entries)) continue
      for (var i = 0; i < entries.length; i++)
        if (Util.canonicalWidgetId(entryId(entries[i])) === id) return true
    }
    return false
  }

  function allowsMultiple(id) {
    var metadata = registry && typeof registry.metadataFor === "function" ? registry.metadataFor(id) : null
    return !!metadata && metadata.allowMultiple === true
  }

  function computeHostedEntries() {
    var out = []
    var seen = {}
    for (var i = 0; i < configuredItems.length; i++) {
      var id = Util.canonicalWidgetId(entryId(configuredItems[i]))
      if (!id || id === root.moduleName) continue
      var multiple = allowsMultiple(id)
      // A second live copy of a single-instance widget would register its IPC
      // target twice, so a widget still on the bar stays on the bar.
      if (!multiple && (seen[id] || inBarLayout(id))) continue
      seen[id] = true
      out.push({ id: id, index: i })
    }
    return out
  }

  function registerSlot(slot) {
    if (!slot || hostedSlots.indexOf(slot) !== -1) return
    var next = hostedSlots.slice()
    next.push(slot)
    hostedSlots = next
  }

  function unregisterSlot(slot) {
    hostedSlots = hostedSlots.filter(function(item) { return item !== slot })
  }

  function orderedSlots() {
    return hostedSlots.slice().sort(function(a, b) { return a.order - b.order })
  }

  function hostedItems(id) {
    var out = []
    for (var i = 0; i < hostedSlots.length; i++) {
      var slot = hostedSlots[i]
      if (slot && slot.activeItem && slot.moduleName === id) out.push(slot.activeItem)
    }
    return out
  }

  function allHostedItems(id) {
    return service && typeof service.hostedWidgets === "function" ? service.hostedWidgets(id) : hostedItems(id)
  }

  function isPanelItem(item) {
    return !!item && typeof item.open === "function" && typeof item.close === "function" && item.opened !== undefined
  }

  function switchHostedPanel(owner, direction) {
    var panels = orderedSlots().filter(function(slot) {
      return slot.activeItem && slot.activeItem.visible && slot.width > 0 && slot.height > 0 && root.isPanelItem(slot.activeItem)
    })
    if (panels.length < 2) return false
    var current = -1
    for (var i = 0; i < panels.length; i++) if (panels[i].activeItem === owner) current = i
    if (current < 0) return false
    var next = panels[(current + (direction < 0 ? -1 : 1) + panels.length) % panels.length]
    next.activeItem.open()
    return true
  }

  // Hotkey bridge: `omarchy-shell parker.drawer togglePanel omarchy.bluetooth`.
  function toggleHostedPanel(id) {
    var key = Util.canonicalWidgetId(String(id || ""))
    var items = hostedItems(key).filter(isPanelItem)
    if (items.length === 0) {
      console.warn("parker.drawer: no hosted panel widget for", key)
      return
    }
    var item = items[0]
    if (drawerOpen && item.opened === true) {
      close()
      return
    }
    if (drawerOpen) {
      item.open()
      return
    }
    open()
    // The drawer surface has to be mapped before a hosted panel can measure
    // its position against it.
    openAfterShow = item
    openAfterShowTimer.restart()
  }

  Timer {
    id: openAfterShowTimer
    interval: 60
    onTriggered: {
      var item = root.openAfterShow
      root.openAfterShow = null
      if (root.drawerOpen && item && typeof item.open === "function") item.open()
    }
  }

  function updateHostedEntry(id, settings) {
    var key = Util.canonicalWidgetId(id)
    var items = configuredItems.slice()
    var index = -1
    for (var i = 0; i < items.length; i++) {
      if (Util.canonicalWidgetId(entryId(items[i])) === key) { index = i; break }
    }
    if (index < 0 || !bar || !bar.shell || typeof bar.shell.updateEntryInline !== "function") return false

    var entry = { id: key }
    for (var k in settings) if (k !== "id") entry[k] = settings[k]
    items[index] = entry

    var own = entrySettings(root.settings)
    own.items = items
    return bar.shell.updateEntryInline(root.moduleName, own)
  }

  // ---------------------------------------------------------------- tooltip

  function clearTooltip() {
    tooltipTimer.stop()
    tooltipTarget = null
    tooltipText = ""
    tooltipShown = false
  }

  function showTooltip(target, text) {
    clearTooltip()
    if (!target || !text) return
    tooltipTarget = target
    tooltipText = text
    tooltipTimer.restart()
  }

  function hideTooltip(target) {
    if (tooltipTarget === target) clearTooltip()
  }

  function tooltipHovered(target) {
    return !!target && target.visible !== false && target.opacity !== 0 && target.tooltipHovered === true
  }

  Timer {
    id: tooltipTimer
    interval: 400
    onTriggered: {
      if (root.tooltipHovered(root.tooltipTarget)) root.tooltipShown = true
      else root.clearTooltip()
    }
  }

  Timer {
    interval: 100
    repeat: true
    running: root.tooltipShown
    onTriggered: if (!root.tooltipHovered(root.tooltipTarget)) root.clearTooltip()
  }

  Timer {
    id: focusPrimeTimer
    interval: 75
    onTriggered: if (root.drawerOpen) root.focusPrimed = true
  }

  // ----------------------------------------------------------------- button

  DrawerBar {
    id: drawerBar
    host: root
    hostBar: root.bar
  }

  function defaultIcon() {
    // Material Design chevrons from the Nerd Font, pointing toward the drawer.
    if (position === "bottom") return String.fromCodePoint(0xF0143)
    if (position === "left") return String.fromCodePoint(0xF0142)
    if (position === "right") return String.fromCodePoint(0xF0141)
    return String.fromCodePoint(0xF0140)
  }

  BarIconButton {
    id: button
    anchors.fill: parent
    bar: root.bar
    text: String(root.setting("icon", "")) || root.defaultIcon()
    textRotation: root.drawerOpen && !String(root.setting("icon", "")) ? 180 : 0
    tooltipText: root.drawerOpen ? "" : "Drawer"

    onPressed: function(mouseButton) {
      if (mouseButton === Qt.LeftButton || mouseButton === Qt.MiddleButton) root.toggle()
    }
  }

  // ----------------------------------------------------------------- drawer

  PanelWindow {
    id: drawerWindow

    screen: root.barWindow ? root.barWindow.screen : null
    visible: root.drawerOpen || card.opacity > 0
    color: "transparent"
    exclusionMode: ExclusionMode.Ignore

    WlrLayershell.namespace: "parker-drawer"
    WlrLayershell.layer: WlrLayer.Overlay
    WlrLayershell.keyboardFocus: root.drawerOpen
      ? (root.focusPrimed ? WlrKeyboardFocus.OnDemand : WlrKeyboardFocus.Exclusive)
      : WlrKeyboardFocus.None

    // Hug the same screen edge as the bar and span the bar, the gap, and the
    // card. Hosted panels place their popups past their window's far edge,
    // so this keeps them opening just beyond the drawer, as they would from
    // the bar. Only the card takes input; the rest is click-through.
    anchors {
      top: root.position === "top" || root.vertical
      bottom: root.position === "bottom" || root.vertical
      left: root.position === "left" || !root.vertical
      right: root.position === "right" || !root.vertical
    }

    implicitHeight: root.vertical ? 0 : Math.ceil(root.barThickness + root.gap + card.height)
    implicitWidth: root.vertical ? Math.ceil(root.barThickness + root.gap + card.width) : 0

    mask: Region { item: card }

    readonly property real spanW: screen ? screen.width : width
    readonly property real spanH: screen ? screen.height : height

    TransformWatcher {
      id: anchorWatcher
      a: root.barWindow ? root.barWindow.contentItem : null
      b: root
    }

    readonly property point anchorCenter: {
      anchorWatcher.transform
      if (!root.barWindow || !root.barWindow.contentItem) return Qt.point(spanW / 2, spanH / 2)
      return root.mapToItem(root.barWindow.contentItem, root.width / 2, root.height / 2)
    }

    BorderSurface {
      id: card

      readonly property real contentW: content.implicitWidth
      readonly property real contentH: content.implicitHeight

      x: {
        if (root.vertical) return root.position === "left" ? root.barThickness + root.gap : 0
        var desired = drawerWindow.anchorCenter.x - width / 2
        return Math.round(Util.clamp(desired, root.margin, Math.max(root.margin, drawerWindow.spanW - width - root.margin)))
      }
      y: {
        if (!root.vertical) return root.position === "bottom" ? 0 : root.barThickness + root.gap
        var desired = drawerWindow.anchorCenter.y - height / 2
        return Math.round(Util.clamp(desired, root.margin, Math.max(root.margin, drawerWindow.spanH - height - root.margin)))
      }
      width: Math.ceil(contentLeftInset + contentRightInset + contentW)
      height: Math.ceil(contentTopInset + contentBottomInset + contentH)

      color: Color.bar.background
      borderSpec: Border.surfaceSpec("popups", "border", Color.popups.border, Math.max(1, Style.space(2)))
      padding: Style.spacing.sm
      radius: Style.cornerRadius
      opacity: root.drawerOpen ? 1 : 0

      Behavior on opacity {
        NumberAnimation { duration: 140; easing.type: Easing.OutCubic }
      }

      // Swallow clicks that land between hosted widgets.
      MouseArea {
        anchors.fill: parent
        acceptedButtons: Qt.AllButtons
      }

      Item {
        id: keyCatcher
        focus: true
        Keys.onEscapePressed: root.close()
      }

      Item {
        id: content
        x: card.contentLeftInset
        y: card.contentTopInset

        readonly property bool empty: root.vertical ? slotGrid.implicitHeight < 1 : slotGrid.implicitWidth < 1

        implicitWidth: empty ? emptyLabel.implicitWidth + Style.space(16) : slotGrid.implicitWidth
        implicitHeight: empty ? root.barSize : slotGrid.implicitHeight

        Text {
          id: emptyLabel
          visible: content.empty
          anchors.centerIn: parent
          text: root.configuredItems.length === 0 ? "Drawer is empty" : "Nothing to show"
          color: drawerBar.foreground
          opacity: 0.6
          font.family: drawerBar.fontFamily
          font.pixelSize: Style.font.body
          rotation: root.vertical ? (root.position === "left" ? 90 : -90) : 0
        }

        Grid {
          id: slotGrid
          spacing: 0
          rows: root.vertical ? Math.max(1, root.hostedEntries.length) : 1
          columns: root.vertical ? 1 : Math.max(1, root.hostedEntries.length)

          Repeater {
            model: root.hostedEntries

            delegate: Item {
              id: slot

              required property var modelData
              required property int index

              readonly property string moduleName: modelData.id
              readonly property int order: index
              readonly property var itemSettings: root.entrySettings(root.configuredItems[modelData.index])
              readonly property var registryComponent: {
                var widgets = root.registry ? root.registry.widgets : null
                var entry = widgets ? widgets[moduleName] : null
                return entry ? entry.component : null
              }
              readonly property Item activeItem: loader.item

              implicitWidth: activeItem && activeItem.visible ? (root.vertical ? root.barSize : activeItem.implicitWidth) : 0
              implicitHeight: activeItem && activeItem.visible ? activeItem.implicitHeight : 0
              width: implicitWidth
              height: implicitHeight

              function injectProps() {
                var target = activeItem
                if (!target) return
                if ("bar" in target) target.bar = drawerBar
                if ("moduleName" in target) target.moduleName = moduleName
                if ("settings" in target) target.settings = itemSettings
              }

              onItemSettingsChanged: injectProps()
              Component.onCompleted: root.registerSlot(slot)
              Component.onDestruction: root.unregisterSlot(slot)

              Loader {
                id: loader
                anchors.fill: parent
                active: slot.registryComponent !== null
                sourceComponent: slot.registryComponent
                onLoaded: {
                  slot.injectProps()
                  Qt.callLater(slot.injectProps)
                }
              }

              // Same open-panel mark the bar draws under a module whose
              // popup is showing, on the edge facing the popup.
              Rectangle {
                readonly property int inset: Style.space(2)
                readonly property real extent: Math.max(Style.space(10), Math.round((root.vertical ? slot.height : slot.width) * 0.55))

                visible: opacity > 0
                opacity: drawerBar.activePopout && drawerBar.activePopout === slot.activeItem ? 0.9 : 0
                color: Color.accent
                radius: Math.min(width, height) / 2
                width: root.vertical ? Style.space(2) : extent
                height: root.vertical ? extent : Style.space(2)
                x: root.vertical
                  ? (root.position === "left" ? slot.width - width - inset : inset)
                  : Math.round((slot.width - width) / 2)
                y: root.vertical
                  ? Math.round((slot.height - height) / 2)
                  : (root.position === "top" ? slot.height - height - inset : inset)
                z: 50

                Behavior on opacity {
                  NumberAnimation { duration: 120; easing.type: Easing.OutCubic }
                }
              }
            }
          }
        }
      }
    }

    PopupWindow {
      id: tooltipWindow

      visible: root.tooltipShown && root.tooltipTarget !== null && root.tooltipText !== ""
        && drawerBar.targetBelongsToWindow(root.tooltipTarget, drawerWindow)
      color: "transparent"
      implicitWidth: Math.ceil(tooltipBubble.implicitWidth)
      implicitHeight: Math.ceil(tooltipBubble.implicitHeight)

      anchor {
        id: tooltipAnchor
        window: drawerWindow
        adjustment: PopupAdjustment.Slide
        edges: Edges.Top | Edges.Left
        gravity: Edges.Bottom | Edges.Right
        rect.width: 1
        rect.height: 1

        onAnchoring: {
          var target = root.tooltipTarget
          if (!drawerBar.targetBelongsToWindow(target, drawerWindow)) return

          var popupWidth = tooltipWindow.implicitWidth
          var popupHeight = tooltipWindow.implicitHeight
          var localX = target.width / 2 - popupWidth / 2
          var localY = target.height + 6

          if (root.position === "bottom") {
            localY = -popupHeight - 6
          } else if (root.position === "left") {
            localX = target.width + 6
            localY = target.height / 2 - popupHeight / 2
          } else if (root.position === "right") {
            localX = -popupWidth - 6
            localY = target.height / 2 - popupHeight / 2
          }

          var point = drawerWindow.contentItem.mapFromItem(target, localX, localY)
          tooltipAnchor.rect.x = Math.round(point.x)
          tooltipAnchor.rect.y = Math.round(point.y)
        }
      }

      BorderSurface {
        id: tooltipBubble
        implicitWidth: tooltipLabel.implicitWidth + 20
        implicitHeight: tooltipLabel.implicitHeight + 14
        color: Color.tooltip.background
        borderSpec: Border.surfaceSpec("tooltip", "border", Color.tooltip.border, 1)
        radius: Style.cornerRadius

        Text {
          id: tooltipLabel
          textFormat: Text.PlainText
          anchors.centerIn: parent
          text: root.tooltipText
          color: Color.tooltip.text
          font.family: drawerBar.fontFamily
          font.pixelSize: Style.font.body
          horizontalAlignment: Text.AlignHCenter
          verticalAlignment: Text.AlignVCenter
        }
      }
    }
  }

  // Outside-click dismissal. Normal exclusion keeps these out of every bar's
  // reserved strip, so clicking another bar widget still reaches it (and the
  // bar's coordinator closes the drawer), while a click anywhere else on any
  // monitor closes the drawer. They sit on the Top layer, under the drawer
  // card and under any popup a hosted widget opens on the Overlay layer.
  Variants {
    model: root.drawerOpen ? Quickshell.screens : []

    delegate: Component {
      PanelWindow {
        required property var modelData

        screen: modelData
        color: "transparent"
        exclusionMode: ExclusionMode.Normal

        WlrLayershell.namespace: "parker-drawer-dismiss"
        WlrLayershell.layer: WlrLayer.Top
        WlrLayershell.keyboardFocus: WlrKeyboardFocus.None

        anchors {
          top: true
          bottom: true
          left: true
          right: true
        }

        MouseArea {
          anchors.fill: parent
          acceptedButtons: Qt.AllButtons
          onPressed: root.close()
        }
      }
    }
  }
}

