import QtQuick
import Quickshell
import Quickshell.Wayland
import qs.Commons
import qs.Ui

ShellRoot {
  id: shellRoot

  readonly property string pluginDir: Quickshell.env("HOME") + "/.config/omarchy/plugins/parker.drawer"
  readonly property string fp: "/usr/share/omarchy/shell/plugins"

  property var widgetComponents: ({})
  property var service: null
  property var savedEntries: []
  property var drawerSettings: ({
    items: [
      "omarchy.clock",
      { id: "omarchy.weather" },
      "omarchy.power",
      "omarchy.audio",
      "parker.drawer",
      "omarchy.clock",
      "does.not.exist"
    ]
  })

  QtObject {
    id: registry
    property var widgets: ({})
    property int revision: 0
    function metadataFor(id) { var e = widgets[String(id)]; return e ? e.metadata : null }
    function availableIds() { return Object.keys(widgets) }
    function has(id) { return widgets[String(id)] !== undefined }
  }

  function loadWidget(id, path) {
    var comp = Qt.createComponent("file://" + path, Component.PreferSynchronous)
    if (comp.status !== Component.Ready) { console.log("TEST comp fail", id, comp.errorString()); return }
    var next = {}
    for (var k in registry.widgets) next[k] = registry.widgets[k]
    next[id] = { component: comp, metadata: { allowMultiple: false } }
    registry.widgets = next
    registry.revision++
  }

  QtObject {
    id: scopedShell
    property var bar: null
    property var barConfig: ({})
    function serviceFor(id) { return id === "parker.drawer" ? shellRoot.service : null }
    function firstPartyServiceFor(id) { return null }
    function summon(id, p) { console.log("TEST summon", id); return false }
    function hide(id) { return false }
    function toggle(id, p) { return false }
    function isPluginOpen(id) { return false }
    function updateEntryInline(id, settings) {
      console.log("TEST updateEntryInline", id, JSON.stringify(settings))
      shellRoot.savedEntries.push({ id: id, settings: settings })
      if (id === "parker.drawer") shellRoot.drawerSettings = settings
      return true
    }
  }

  property var activePopout: null

  PluginBarApi {
    id: pluginBar
    pluginId: "parker.drawer"
    moduleName: "parker.drawer"
    shell: scopedShell
    foreground: "#cacccc"
    barForeground: "#cacccc"
    background: "#101010"
    urgent: "#ff0000"
    fontFamily: "monospace"
    position: Quickshell.env("TEST_POS") || "top"
    vertical: position === "left" || position === "right"
    barSize: vertical ? 28 : 26
    layoutConfig: ({ left: [{ id: "omarchy.menu" }], center: [{ id: "omarchy.audio" }], right: [{ id: "parker.drawer" }] })
    _requestPopout: function(owner) { console.log("TEST bar.requestPopout"); shellRoot.activePopout = owner }
    _releasePopout: function(owner) { console.log("TEST bar.releasePopout"); if (shellRoot.activePopout === owner) shellRoot.activePopout = null }
    _run: function(c) { console.log("TEST run", c) }
  }

  PanelWindow {
    id: barWindow
    anchors { top: pluginBar.position !== "bottom"; bottom: pluginBar.position !== "top"; left: pluginBar.position !== "right"; right: pluginBar.position !== "left" }
    implicitHeight: pluginBar.vertical ? 0 : 26
    implicitWidth: pluginBar.vertical ? 28 : 0
    color: "#101010"

    Row {
      anchors.right: parent.right
      Item { width: 300; height: 26 }
      Loader {
        id: drawerLoader
        active: false
        source: "file://" + shellRoot.pluginDir + "/Widget.qml"
        onLoaded: {
          item.bar = pluginBar
          item.moduleName = "parker.drawer"
          item.settings = Qt.binding(function() { return shellRoot.drawerSettings })
        }
        onStatusChanged: if (status === Loader.Error) console.log("TEST widget load error")
      }
    }
  }

  function dump(label) {
    var w = drawerLoader.item
    var ids = w.hostedSlots.map(function(s) { return s.moduleName + "[" + (s.activeItem ? "item " + Math.round(s.width) + "x" + Math.round(s.height) : "none") + "]" })
    console.log("TEST", label, "open=" + w.opened, "entries=" + w.hostedKey, "slots=" + ids.join(","))
  }

  Timer {
    id: steps
    property int step: 0
    interval: 400
    repeat: true
    running: true
    onTriggered: {
      var w = drawerLoader.item
      step++
      try {
        if (step === 1) {
          var sc = Qt.createComponent("file://" + shellRoot.pluginDir + "/Service.qml", Component.PreferSynchronous)
          if (sc.status !== Component.Ready) console.log("TEST service fail", sc.errorString())
          shellRoot.service = sc.createObject(null)
